head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst20200";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst20200.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_listApplntIsurCd", fn: function () { return String(String((dma_pageContext.get("listApplntIsurCd") ?? ""))); } },
        { childId: "ipt_listApplntIsurNm", fn: function () { return String(String((dma_pageContext.get("listApplntIsurNm") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    $("#ipt_listApplntIsurNm").bind("change", function() {
            $c.util.getComponent('ipt_listApplntIsurCd').setValue("");
            $c.util.getComponent('ipt_listApplntIsurCd2').setValue("");
    });
    $("#ipt_listApplntIsurNm").bind("keypress", async function(e) {
            if (e.keyCode === 13) {
                if ($c.util.getComponent('ipt_listApplntIsurNm').getValue() !== $c.util.getComponent('ipt_listApplntIsurCd2').getValue()) {
                    $c.util.getComponent('ipt_listApplntIsurCd').setValue("");
                    $c.util.getComponent('ipt_listApplntIsurCd2').setValue("");
                }
                await scwin.fnSearchInit();
            }
    });
    $c.util.getComponent("dma_fnDownloadReq").set("method", "digitalCorpListPopSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "digital_corp_sub");
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20200.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_findDigitalListApplnt_onclick
 * @description btn_findDigitalListApplnt 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findDigitalListApplnt_onclick = function(e){
    try {
        scwin.findDigitalListApplnt();return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst20200.btn_findDigitalListApplnt_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        await scwin.fnSearchInit(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20200.btn_fnSearchInit_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload();return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst20200.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/digital/digitalCorpListPop.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/digital/digitalCorpListPop.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name findDigitalListApplnt
 * @description find Digital List Applnt 처리
 * @returns {void}
 * @hidden N
 */
scwin.findDigitalListApplnt = function () {
    scwin.fnMarketType();
    const marketType = $c.util.getComponent('ipt_marketType').getValue();
    findDigitalListApplntIsurCd(marketType);
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    scwin.fnMarketType();
    $c.util.getComponent('ipt_beginIndex').setValue("");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "digitalCorpListPopSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "digital_corp_sub");
    $("#searchForm").attr('onsubmit', 'return false;');
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name fnMarketType
 * @description fn Market Type 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnMarketType = function () {
    $c.util.getComponent('ipt_marketType').setValue(0);
    let i = 0;
    let j = 0;
    const marketType1 = $("#ipt_marketType1").is(":checked");
    const marketType2 = $("#ipt_marketType2").is(":checked");
    if (marketType1 === true) {
        i = 1;
    }
    if (marketType2 === true) {
        j = 2;
    }
    const c = i + j;
    $c.util.getComponent('ipt_marketType').setValue(c);
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $c.util.getComponent("ipt_currentPageSize").getValue());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "digitalCorpListPopSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "digital_corp_down");
    $("#searchForm").attr('onsubmit', '');
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name setDigitallistApplntInfo
 * @description set Digitallist Applnt Info 처리
 * @param {String} ipt_listApplntIsurCd ipt_listApplntIsurCd
 * @param {String} ipt_listApplntIsurNm ipt_listApplntIsurNm
 * @returns {void}
 * @hidden N
 */
scwin.setDigitallistApplntInfo = function (ipt_listApplntIsurCd, ipt_listApplntIsurNm) {
    $c.util.getComponent('ipt_listApplntIsurCd2').setValue(ipt_listApplntIsurCd);
    $c.util.getComponent('ipt_listApplntIsurNm').setValue(ipt_listApplntIsurCd);
};
